alter table public.melo_channel_posts add column pinned boolean not null default false, add column edited_at timestamptz;
grant update(body,pinned,edited_at) on public.melo_channel_posts to authenticated;
create policy channel_post_edit on public.melo_channel_posts for update to authenticated using(exists(select 1 from public.melo_channels c where c.id=channel_id and c.owner_id=(select auth.uid()))) with check(exists(select 1 from public.melo_channels c where c.id=channel_id and c.owner_id=(select auth.uid())));
create table public.melo_post_views(post_id uuid references public.melo_channel_posts(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,primary key(post_id,user_id));
alter table public.melo_post_views enable row level security;
revoke all on public.melo_post_views from public,anon,authenticated;
grant insert(post_id,user_id) on public.melo_post_views to authenticated;
grant select on public.melo_post_views to authenticated;
create policy own_post_views_read on public.melo_post_views for select to authenticated using(user_id=(select auth.uid()));
create policy own_post_views_insert on public.melo_post_views for insert to authenticated with check(user_id=(select auth.uid()));
create function private.melo_view_counts(ids uuid[]) returns table(post_id uuid,views bigint) language sql stable security definer set search_path='' as $$select v.post_id,count(*) from public.melo_post_views v where auth.uid() is not null and cardinality(ids)<=150 and v.post_id=any(ids) group by v.post_id$$;
revoke all on function private.melo_view_counts(uuid[]) from public,anon,authenticated;
grant execute on function private.melo_view_counts(uuid[]) to authenticated;
create function public.melo_view_counts(ids uuid[]) returns table(post_id uuid,views bigint) language sql stable security invoker set search_path='' as $$select * from private.melo_view_counts(ids)$$;
revoke all on function public.melo_view_counts(uuid[]) from public,anon,authenticated;
grant execute on function public.melo_view_counts(uuid[]) to authenticated;
create table public.melo_bots(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id) on delete cascade,name text not null check(char_length(trim(name)) between 1 and 50),description text not null default '' check(char_length(description)<=240),commands jsonb not null default '{}' check(jsonb_typeof(commands)='object' and octet_length(commands::text)<=10000),created_at timestamptz not null default now());
alter table public.melo_bots enable row level security;
revoke all on public.melo_bots from public,anon,authenticated;
grant select,delete on public.melo_bots to authenticated;
grant insert(owner_id,name,description,commands),update(name,description,commands) on public.melo_bots to authenticated;
create policy bots_read on public.melo_bots for select to authenticated using(true);
create policy bots_create on public.melo_bots for insert to authenticated with check(owner_id=(select auth.uid()));
create policy bots_edit on public.melo_bots for update to authenticated using(owner_id=(select auth.uid())) with check(owner_id=(select auth.uid()));
create policy bots_delete on public.melo_bots for delete to authenticated using(owner_id=(select auth.uid()));
create table public.melo_reports(id uuid primary key default gen_random_uuid(),reporter_id uuid not null references public.profiles(id) on delete cascade,target_type text not null check(target_type in ('user','post')),target_id uuid not null,reason text not null check(char_length(trim(reason)) between 1 and 500),status text not null default 'open' check(status in ('open','resolved','dismissed')),created_at timestamptz not null default now(),unique(reporter_id,target_type,target_id));
alter table public.melo_reports enable row level security;
revoke all on public.melo_reports from public,anon,authenticated;
grant select on public.melo_reports to authenticated;
grant insert(reporter_id,target_type,target_id,reason),update(status) on public.melo_reports to authenticated;
create policy report_read on public.melo_reports for select to authenticated using(reporter_id=(select auth.uid()) or exists(select 1 from public.melo_admins where user_id=(select auth.uid())));
create policy report_create on public.melo_reports for insert to authenticated with check(reporter_id=(select auth.uid()) and ((target_type='user' and target_id<>(select auth.uid()) and exists(select 1 from public.profiles p where p.id=target_id)) or (target_type='post' and exists(select 1 from public.melo_channel_posts p where p.id=target_id))));
create policy report_review on public.melo_reports for update to authenticated using(exists(select 1 from public.melo_admins where user_id=(select auth.uid()))) with check(exists(select 1 from public.melo_admins where user_id=(select auth.uid())));
create function private.melo_moderate_post(report_id uuid) returns void language plpgsql security definer set search_path='' as $$
declare report public.melo_reports%rowtype;
begin
 if auth.uid() is null or not exists(select 1 from public.melo_admins where user_id=auth.uid() and is_owner) then raise exception 'Owner access required' using errcode='42501';end if;
 select * into report from public.melo_reports where id=report_id and target_type='post' and status='open' for update;
 if not found then raise exception 'Report unavailable';end if;
 delete from public.melo_channel_posts where id=report.target_id;
 update public.melo_reports set status='resolved' where id=report_id;
end $$;
revoke all on function private.melo_moderate_post(uuid) from public,anon,authenticated;
grant execute on function private.melo_moderate_post(uuid) to authenticated;
create function public.melo_moderate_post(report_id uuid) returns void language sql security invoker set search_path='' as $$select private.melo_moderate_post(report_id)$$;
revoke all on function public.melo_moderate_post(uuid) from public,anon,authenticated;
grant execute on function public.melo_moderate_post(uuid) to authenticated;
create function private.melo_sessions() returns table(id uuid,created_at timestamptz,updated_at timestamptz,user_agent text,current_session boolean) language sql stable security definer set search_path='' as $$select s.id,s.created_at,s.updated_at,s.user_agent,s.id::text=auth.jwt()->>'session_id' from auth.sessions s where s.user_id=auth.uid() and (s.not_after is null or s.not_after>now()) order by s.updated_at desc$$;
revoke all on function private.melo_sessions() from public,anon,authenticated;
grant execute on function private.melo_sessions() to authenticated;
create function public.melo_sessions() returns table(id uuid,created_at timestamptz,updated_at timestamptz,user_agent text,current_session boolean) language sql stable security invoker set search_path='' as $$select * from private.melo_sessions()$$;
revoke all on function public.melo_sessions() from public,anon,authenticated;
grant execute on function public.melo_sessions() to authenticated;